using AcxiomCrm.Models;using AcxiomCrm.Services;using Microsoft.AspNetCore.Authorization;using Microsoft.AspNetCore.Identity;using Microsoft.AspNetCore.Mvc;using Microsoft.EntityFrameworkCore;
namespace AcxiomCrm.Controllers;
[Authorize(Roles="Admin,Manager")]public class UsersController:Controller{private readonly UserManager<ApplicationUser> _users;private readonly RoleManager<IdentityRole> _roles;private readonly AuditService _audit;public UsersController(UserManager<ApplicationUser> users,RoleManager<IdentityRole> roles,AuditService audit){_users=users;_roles=roles;_audit=audit;}
public IActionResult Index()=>View(_users.Users.OrderBy(x=>x.Email).ToList());
[Authorize(Roles="Admin")]
public async Task<IActionResult>Edit(string id){var u=await _users.FindByIdAsync(id);if(u==null)return NotFound();ViewData["Roles"] = await _roles.Roles.Select(x=>x.Name!).ToListAsync();ViewData["CurrentRole"] = (await _users.GetRolesAsync(u)).FirstOrDefault();return View(u);}
[HttpPost,Authorize(Roles="Admin"),ValidateAntiForgeryToken]public async Task<IActionResult>Edit(string id,string fullName,string role,bool active){var u=await _users.FindByIdAsync(id);if(u==null)return NotFound();u.FullName=fullName;u.EmailConfirmed=true;u.LockoutEnabled=true;u.LockoutEnd=active?null:DateTimeOffset.UtcNow.AddYears(10);var r=await _users.UpdateAsync(u);if(!r.Succeeded){foreach(var e in r.Errors)ModelState.AddModelError("",e.Description);return View(u);}var oldRoles=await _users.GetRolesAsync(u);await _users.RemoveFromRolesAsync(u,oldRoles);if(!await _roles.RoleExistsAsync(role))await _roles.CreateAsync(new IdentityRole(role));await _users.AddToRoleAsync(u,role);await _audit.LogAsync("Role Change","User",id,newValue:new{role,active});return RedirectToAction(nameof(Index));}
}
